package main
import("testing";"time";"strings";"net/http";"net/http/httptest";"sync";"sync/atomic";"os";"path/filepath";"crypto/tls";"errors";"fmt")
func TestOwnFetchMatrix(t *testing.T){for _,name:=range []string{"http","redirect","4097","bad-json","missing-sig-allowed","wrong-sig-ignored","replay","valid","tls-untrusted","timeout5"}{t.Run(name,func(t *testing.T){fxReset(t);var followed atomic.Int32;dest:=httptest.NewTLSServer(http.HandlerFunc(func(w http.ResponseWriter,r *http.Request){followed.Add(1)}));defer dest.Close();body:=fxBody;if name=="4097"{body+=strings.Repeat(" ",4097-len(body))};if name=="bad-json"{body="{"};if name=="replay"{body=strings.Replace(body,"2026-11-06","2026-11-01",1)}
 s:=httptest.NewTLSServer(http.HandlerFunc(func(w http.ResponseWriter,r *http.Request){if name=="redirect"{http.Redirect(w,r,dest.URL,302);return};if name=="timeout5"{select{case<-r.Context().Done():return;case<-time.After(7*time.Second):}};if name=="wrong-sig-ignored"{w.Header().Set("X-Kanus-FX-Signature","wrong")};w.Write([]byte(body))}));defer s.Close();old:=fxHTTP;defer func(){fxHTTP=old}();tr:=fxTransport();tr.TLSClientConfig.RootCAs=s.Client().Transport.(*http.Transport).TLSClientConfig.RootCAs;if name=="tls-untrusted"{tr=fxTransport()};defer tr.CloseIdleConnections();fxHTTP=&http.Client{Timeout:5*time.Second,Transport:tr,CheckRedirect:old.CheckRedirect};u:=s.URL;if name=="http"{u="http://127.0.0.1:1"};start:=time.Now();_,_,_,err:=fetchFX(u);d:=time.Since(start);wantOK:=name=="valid"||name=="missing-sig-allowed"||name=="wrong-sig-ignored";if(err==nil)!=wantOK{t.Fatal(err)};t.Log(name,err,d);if followed.Load()!=0{t.Fatal("redirect followed")};if name=="timeout5"&&(d<4800*time.Millisecond||d>6500*time.Millisecond){t.Fatal(d)}})}}
func TestOwnCacheMatrix(t *testing.T){for _,name:=range []string{"valid","local-tamper","corrupt","stale","symlink","root-swap","max-body-cache"}{t.Run(name,func(t *testing.T){fxReset(t);dir:=filepath.Dir(os.Getenv("US_DESK"));body:=fxBody;if name=="local-tamper"{body=strings.ReplaceAll(strings.ReplaceAll(body,"50.0724","40"),"55.9609","44")};if name=="stale"{body=strings.Replace(body,"2026-11-06","2026-11-01",1)};if name=="max-body-cache"{body+=strings.Repeat(" ",4096-len(body))};raw:=[]byte(body);if name=="corrupt"{raw=[]byte("{")}
 if name=="symlink"{out:=t.TempDir();v:=filepath.Join(out,"victim");os.WriteFile(v,[]byte("sentinel"),0600);os.Symlink(v,filepath.Join(dir,"fx.json"));_=fxCache.WriteRaw(raw);got,_:=os.ReadFile(v);if string(got)!="sentinel"{t.Fatal("outside write")};return}
 if name=="root-swap"{if e:=fxCache.WriteRaw(raw);e!=nil{t.Fatal(e)};moved:=dir+"-moved";if e:=os.Rename(dir,moved);e!=nil{t.Fatal(e)};defer os.RemoveAll(moved);out:=t.TempDir();os.WriteFile(filepath.Join(out,"fx.json"),[]byte("sentinel"),0600);if e:=os.Symlink(out,dir);e!=nil{t.Fatal(e)};_=fxCache.WriteRaw(raw);got,_:=os.ReadFile(filepath.Join(out,"fx.json"));if string(got)!="sentinel"{t.Fatal("swap outside write")};return}
 if name=="max-body-cache"{s:=newFXServer(t,serve(body));refreshFX(s.URL);_,ok:=fxFromCache();if !ok{t.Fatal("4096 cache missing")};return}
 if e:=os.WriteFile(filepath.Join(dir,"fx.json"),raw,0600);e!=nil{t.Fatal(e)};got,ok:=fxFromCache();want:=name=="valid"||name=="local-tamper";if ok!=want{t.Fatal(ok)};if name=="local-tamper"&&got.USD!=40{t.Fatal(got)}
 })}}
func TestOwnConcurrentRefresh(t *testing.T){fxReset(t);s:=newFXServer(t,func(w http.ResponseWriter,r *http.Request){time.Sleep(50*time.Millisecond);serve(fxBody)(w,r)});fxSetState(true,time.Time{});var wg sync.WaitGroup;for i:=0;i<100;i++{wg.Add(1);go func(){defer wg.Done();currentFX()}()};wg.Wait();fxWaitIdle(t);for i:=0;i<100;i++{currentFX()};if s.hits.Load()!=1{t.Fatal(s.hits.Load())}}
func TestOwnPricingCannotOverrideGateway(t *testing.T){fxReset(t);s:=newFXServer(t,serve(fxBody));t.Setenv("US_GATEWAY_URL","https://invalid.invalid");fxSetState(true,time.Time{});w:=httptest.NewRecorder();pricingHandler(w,httptest.NewRequest("GET","/api/pricing?lang=en&gateway=https://invalid.invalid",nil));fxWaitIdle(t);if s.hits.Load()!=1{t.Fatal(s.hits.Load())}}
func TestOwnTLSMore(t *testing.T){for _,name:=range []string{"hostname","tls11"}{t.Run(name,func(t *testing.T){fxReset(t);s:=httptest.NewUnstartedServer(http.HandlerFunc(serve(fxBody)));if name=="tls11"{s.TLS=&tls.Config{MinVersion:tls.VersionTLS11,MaxVersion:tls.VersionTLS11}};s.StartTLS();defer s.Close();tr:=fxTransport();tr.TLSClientConfig.RootCAs=s.Client().Transport.(*http.Transport).TLSClientConfig.RootCAs;if name=="hostname"{tr.TLSClientConfig.ServerName="wrong.invalid"};defer tr.CloseIdleConnections();old:=fxHTTP;fxHTTP=&http.Client{Timeout:5*time.Second,Transport:tr,CheckRedirect:old.CheckRedirect};defer func(){fxHTTP=old}();_,_,_,e:=fetchFX(s.URL);if e==nil{t.Fatal("invalid TLS accepted")};t.Log(e)})}}
func TestOwnUnsignedExtras(t *testing.T){for _,name:=range []string{"4097-cache","write-log","503-envelope","stale-fallback","base-fixed","production-test-value"}{t.Run(name,func(t *testing.T){fxReset(t);switch name{
case "4097-cache":if e:=fxCache.WriteRaw([]byte(strings.Repeat("x",4097)));e==nil{t.Fatal("oversize accepted")}
case "write-log":s:=newFXServer(t,serve(fxBody));os.Mkdir(cacheFile(),0700);old:=fxLogf;var logs []string;fxLogf=func(f string,a ...any){logs=append(logs,fmt.Sprintf(f,a...))};defer func(){fxLogf=old}();refreshFX(s.URL);if !strings.Contains(strings.Join(logs," "),"fx cache not saved"){t.Fatal(logs)}
case "503-envelope":s:=newFXServer(t,func(w http.ResponseWriter,r *http.Request){w.WriteHeader(503);w.Write([]byte(`{"error":"Service unavailable","code":"fx_unavailable","request_id":"synthetic"}`))});_,_,_,e:=fetchFX(s.URL);if !errors.Is(e,errFXUnavailable){t.Fatal(e)}
case "stale-fallback":s:=newFXServer(t,serve(fxBody));refreshFX(s.URL);fx.mu.Lock();fx.next=time.Date(2100,1,1,0,0,0,0,time.UTC);fx.mu.Unlock();fxNow=func()time.Time{return time.Date(2026,11,11,23,59,59,0,time.FixedZone("TSI",10800))};if !strings.Contains(pricingSummaryFor("en"),"≈"){t.Fatal("fifth day hidden")};fxNow=func()time.Time{return time.Date(2026,11,12,0,0,0,0,time.FixedZone("TSI",10800))};fx.mu.Lock();fx.next=fxNow().Add(time.Hour);fx.mu.Unlock();if strings.Contains(pricingSummaryFor("en"),"≈"){t.Fatal("sixth day FX shown")}
case "base-fixed","production-test-value":oldL,oldG,oldO,oldC:=embeddedLicenseURL,embeddedGatewayURL,fxBaseOverride,releaseChannel;defer func(){embeddedLicenseURL,embeddedGatewayURL,fxBaseOverride,releaseChannel=oldL,oldG,oldO,oldC}();fxBaseOverride="";embeddedLicenseURL="";embeddedGatewayURL="";t.Setenv("US_LICENSE_URL",fxTestBase);t.Setenv("US_GATEWAY_URL",fxTestBase);os.WriteFile(os.Getenv("US_DESK"),[]byte(`{"gateway":"https://evil.invalid","fxBase":"https://evil.invalid"}`),0600);if fxBase()!=fxLiveBase{t.Fatal(fxBase())};if name=="production-test-value"{releaseChannel="commercial";embeddedLicenseURL=fxTestBase;if fxBase()!=fxTestBase{t.Fatal(fxBase())};t.Log("commercial channel with compiled test host resolves api-test; build setting, not runtime override")}
}})}}
